extends VBoxContainer

@onready var name_input: LineEdit = %NameInput
@onready var difficulty_slider: HSlider = %DifficultySlider
@onready var difficulty_bar: ProgressBar = %DifficultyBar
@onready var powerups_check: CheckBox = %PowerupsCheck
@onready var summary_label: Label = %SummaryLabel
@onready var start_button: Button = %StartButton


func _ready() -> void:
	# Configura i limiti numerici del cursore e della barra
	difficulty_slider.min_value = 1.0
	difficulty_slider.max_value = 5.0
	difficulty_slider.step = 1.0
	difficulty_slider.value = 2.0

	difficulty_bar.min_value = difficulty_slider.min_value
	difficulty_bar.max_value = difficulty_slider.max_value
	difficulty_bar.value = difficulty_slider.value

	# Imposta i testi di suggerimento e lo stato iniziale
	name_input.placeholder_text = "Inserisci il tuo nome..."
	powerups_check.text = "Attiva oggetti rari (rubini)"
	start_button.text = "Gioca"
	start_button.disabled = true

	# Connette i segnali per reagire alle azioni del giocatore
	name_input.text_changed.connect(_on_name_input_text_changed)
	difficulty_slider.value_changed.connect(_on_difficulty_slider_value_changed)
	powerups_check.toggled.connect(_on_powerups_check_toggled)
	start_button.pressed.connect(_on_start_button_pressed)

	_update_summary()


func _on_name_input_text_changed(new_text: String) -> void:
	# strip_edges rimuove gli spazi vuoti prima e dopo il testo
	var trimmed_name: String = new_text.strip_edges()
	start_button.disabled = (trimmed_name == "")
	_update_summary()


func _on_difficulty_slider_value_changed(new_value: float) -> void:
	# Sincronizza la barra visiva con la posizione del cursore
	difficulty_bar.value = new_value
	_update_summary()


func _on_powerups_check_toggled(_toggled_on: bool) -> void:
	_update_summary()


func _on_start_button_pressed() -> void:
	print("Partita avviata per: ", name_input.text.strip_edges())
	print("Livello difficoltà scelto: ", difficulty_slider.value)
	print("Potenziamenti abilitati: ", powerups_check.button_pressed)


func _update_summary() -> void:
	var player_name: String = name_input.text.strip_edges()
	if player_name == "":
		player_name = "(nessun nome)"

	var bonus_status: String = "No"
	if powerups_check.button_pressed:
		bonus_status = "Sì"

	var diff_level: int = int(difficulty_slider.value)
	summary_label.text = "Profilo: " + player_name + " | Difficoltà: " + str(diff_level) + " | Rubini: " + bonus_status

esercizi.consegna:
Crea la schermata «Nuova partita» per raccogliere il nome del giocatore e impostare la partita.

1. Crea la scena `res://new_game.tscn` con radice di tipo `VBoxContainer` chiamata `NewGameMenu`.
2. All'interno di `NewGameMenu` aggiungi nell'ordine:
   - un `TextureRect` chiamato `LogoRect` con la texture `res://icon.svg`;
   - una `Label` chiamata `TitleLabel` con testo `Nuova Partita`;
   - un `LineEdit` chiamato `NameInput`;
   - un `HSlider` chiamato `DifficultySlider`;
   - una `ProgressBar` chiamata `DifficultyBar`;
   - una `CheckBox` chiamata `PowerupsCheck`;
   - una `Label` chiamata `SummaryLabel`;
   - un `Button` chiamato `StartButton`.
3. Attiva **Access as Unique Name** (`%`) per `NameInput`, `DifficultySlider`, `DifficultyBar`, `PowerupsCheck`, `SummaryLabel` e `StartButton`.
4. Crea e assegna a `NewGameMenu` lo script `res://new_game.gd`. In `_ready()`:
   - imposta il cursore `DifficultySlider` con valori da `1.0` a `5.0`, passo `1.0` e valore iniziale `2.0`;
   - sincronizza `DifficultyBar` con gli stessi limiti e lo stesso valore iniziale;
   - assegna a `NameInput` il testo di suggerimento `"Inserisci il tuo nome..."`;
   - assegna a `PowerupsCheck` il testo `"Attiva oggetti rari (rubini)"`;
   - imposta il testo di `StartButton` su `"Gioca"` e disattivalo (`disabled = true`);
   - collega i segnali appropriati in modo che digitando un nome non vuoto `StartButton` si abiliti, spostando il cursore la barra si aggiorni e `SummaryLabel` mostri il riepilogo aggiornato (`"Giocatore: ... | Difficoltà: ... | Oggetti rari: ..."`).

